<script setup>
import {computed} from 'vue';
import {paginationItems} from '../lib/pagination';
const props=defineProps({modelValue:Number,total:Number,count:Number});const emit=defineEmits(['update:modelValue']);const numbers=computed(()=>paginationItems(props.modelValue,props.total));function go(n){if(n>=1&&n<=props.total&&n!==props.modelValue)emit('update:modelValue',n);}
</script>
<template><nav class="numbered-pagination" aria-label="Paginación de productos"><div class="pagination-controls"><button type="button" class="page-direction" :disabled="modelValue===1" aria-label="Ir a la primera página" title="Inicio" @click="go(1)"><span aria-hidden="true">«</span></button><button type="button" class="page-direction" :disabled="modelValue===1" aria-label="Página anterior" title="Atrás" @click="go(modelValue-1)"><span aria-hidden="true">‹</span></button><div class="page-numbers"><template v-for="n in numbers" :key="n"><button v-if="typeof n==='number'" type="button" :class="{active:n===modelValue}" :aria-current="n===modelValue?'page':undefined" :aria-label="'Página '+n" @click="go(n)">{{n}}</button><span v-else class="page-ellipsis" aria-hidden="true">…</span></template></div><button type="button" class="page-direction" :disabled="modelValue===total" aria-label="Página siguiente" title="Adelante" @click="go(modelValue+1)"><span aria-hidden="true">›</span></button><button type="button" class="page-direction" :disabled="modelValue===total" aria-label="Ir a la última página" title="Fin" @click="go(total)"><span aria-hidden="true">»</span></button></div><p aria-live="polite">Página <strong>{{modelValue}}</strong> de {{total}} <span>·</span> {{count}} productos</p></nav></template>